    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Konfigurer systemomfattende innstillinger: Basis-URL, sikkerhet, standardspråk, tidssone, standardinnstillinger for risikovurdering og mer.',
    'SettingsPreferencesDesc'             => 'Standardverdier og atferdsinnstillinger på tvers av SimpleRisk: språk, tidssone, revisjonsstatuser, krav til risikokartlegging, brytere for brukergrensesnittatferd og lignende.',
    'SettingsFileUploadDesc'              => 'Tillatte filopplastingstyper og størrelsesgrenser for de ulike feltene for filvedlegg.',
